 63	export function bestBy(arr, by, compare) {
 64	  if (arr.length === 0) {
 65	    return undefined;
 66	  }
 67	  return arr.reduce((best, next) => {
 68	    const pair = [by(next), next];
 69	    if (!best) {
 70	      return pair;
 71	    } else if (compare(best[0], pair[0]) === best[0]) {
