194	export function parseZoneInfo(ts, offsetFormat, locale, timeZone = null) {
195	  const date = new Date(ts),
196	    intlOpts = {
197	      hour12: false,
198	      year: "numeric",
199	      month: "2-digit",
200	      day: "2-digit",
201	      hour: "2-digit",
202	      minute: "2-digit"
203	    };
