cd /luxon && cat > tmp-probe-dst.js <<'EOF'
import { DateTime } from "./src/luxon.js";

let failures = 0;
const check = (label, actual, expected) => {
  const ok = actual === expected;
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${label}: got ${actual} want ${expected}`);
};

// 1) 1974 whole year in America/New_York, hour 4 (as in existing `dt()` helper)
{
  const zoned = DateTime.fromMillis(391147200000).setZone("America/New_York"); // 1982-05-25T04:00Z
  let d = zoned.set({ year: 1974, month: 1, day: 1 });
  const end = zoned.set({ year: 1975, month: 1, day: 1 });
  let firstTrue = null, lastTrue = null, wrong = [];
  while (d < end) {
    const iso = d.toISODate();
    const expected = iso >= "1974-01-06" && iso <= "1974-10-27";
    if (d.isInDST !== expected) wrong.push([iso, d.isInDST, expected]);
    if (d.isInDST && !firstTrue) firstTrue = iso;
    if (d.isInDST) lastTrue = iso;
    d = d.plus({ days: 1 });
  }
  check("1974 hour-4 first true day", firstTrue, "1974-01-06");
  check("1974 hour-4 last true day", lastTrue, "1974-10-27");
  check("1974 hour-4 wrong-day count", wrong.length, 0);
  if (wrong.length) console.log("  wrong:", wrong.slice(0, 10));
}

// 2) midnight loop (documenting that Jan 6 00:00 EST is genuinely not DST)
{
  let d = DateTime.fromObject({ year: 1974, month: 1, day: 1 }, { zone: "America/New_York" });
  const end = DateTime.fromObject({ year: 1975, month: 1, day: 1 }, { zone: "America/New_York" });
  let firstTrue = null, lastTrue = null;
  while (d < end) {
    if (d.isInDST) { if (!firstTrue) firstTrue = d.toISODate(); lastTrue = d.toISODate(); }
    d = d.plus({ days: 1 });
  }
  console.log(`INFO midnight loop: first true ${firstTrue}, last true ${lastTrue}`);
}

// 3) explicit spot checks from the bug report
check("1974-06-01 NY", DateTime.fromISO("1974-06-01", { zone: "America/New_York" }).isInDST, true);
check("1974-01-05 NY", DateTime.fromISO("1974-01-05", { zone: "America/New_York" }).isInDST, false);
check("1974-01-06T12 NY", DateTime.fromISO("1974-01-06T12:00", { zone: "America/New_York" }).isInDST, true);
check("1974-10-27T12 NY", DateTime.fromISO("1974-10-27T12:00", { zone: "America/New_York" }).isInDST, true);
check("1974-10-28T12 NY", DateTime.fromISO("1974-10-28T12:00", { zone: "America/New_York" }).isInDST, false);
check("1974-12-31T12 NY", DateTime.fromISO("1974-12-31T12:00", { zone: "America/New_York" }).isInDST, false);

// 4) normal years
for (const y of [2016, 2017, 2018]) {
  let d = DateTime.fromObject({ year: y, month: 1, day: 1, hour: 12 }, { zone: "America/New_York" });
  const end = DateTime.fromObject({ year: y + 1, month: 1, day: 1, hour: 12 }, { zone: "America/New_York" });
  let t = 0, f = 0;
  while (d < end) { d.isInDST ? t++ : f++; d = d.plus({ days: 1 }); }
  console.log(`INFO ${y} NY: true=${t} false=${f}`);
}
check("2017-01-15 NY", DateTime.fromISO("2017-01-15T12:00", { zone: "America/New_York" }).isInDST, false);
check("2017-07-15 NY", DateTime.fromISO("2017-07-15T12:00", { zone: "America/New_York" }).isInDST, true);
check("2017-12-15 NY", DateTime.fromISO("2017-12-15T12:00", { zone: "America/New_York" }).isInDST, false);

// 5) southern hemisphere + fixed offsets + invalid
check("Sydney 2017-01-15", DateTime.fromISO("2017-01-15T12:00", { zone: "Australia/Sydney" }).isInDST, true);
check("Sydney 2017-07-15", DateTime.fromISO("2017-07-15T12:00", { zone: "Australia/Sydney" }).isInDST, false);
check("Sydney 2017-12-15", DateTime.fromISO("2017-12-15T12:00", { zone: "Australia/Sydney" }).isInDST, true);
check("UTC", DateTime.utc().isInDST, false);
check("UTC+5", DateTime.fromMillis(391147200000).toUTC(5 * 60).isInDST, false);
check("invalid", DateTime.invalid("because").isInDST, false);

// 6) existing test expectations from test/datetime/zone.test.js
{
  const zoned = DateTime.fromMillis(391147200000).setZone("America/Los_Angeles");
  check("LA set month 1", zoned.set({ month: 1 }).isInDST, false);
  check("LA set month 5", zoned.set({ month: 5 }).isInDST, true);
  check("LA set month 12", zoned.set({ month: 12 }).isInDST, false);
  check("LA 1982-05-24", zoned.isInDST, true);
}
console.log(failures === 0 ? "ALL PROBE CHECKS PASSED" : `${failures} PROBE CHECKS FAILED`);
EOF
