143	export function daysInMonth(year, month) {
144	  const modMonth = floorMod(month - 1, 12) + 1,
145	    modYear = year + (month - modMonth) / 12;
146	
147	  if (modMonth === 2) {
148	    return isLeapYear(modYear) ? 29 : 28;
149	  } else {
150	    return [31, null, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][modMonth - 1];
151	  }
