154	// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
155	export function objToLocalTS(obj) {
156	  // for legacy reasons, the Date constructor interprets years between 0 and 99 as 19XX.
157	  // We can't just use Date.UTC and then shift the resulting year back, because the
158	  // intermediate year can be a different kind of leap year (e.g. 1900 vs 0, or 2000 vs
159	  // 100), which throws off the month/day overflow arithmetic. So set the year directly.
160	  const d = new Date(0);
161	  d.setUTCFullYear(obj.year, obj.month - 1, obj.day);
162	  d.setUTCHours(obj.hour, obj.minute, obj.second, obj.millisecond);
163	  return +d;
164	}
